-- Staging top-up: demo content, part 2a, file 1 of 7. GENERATED by npm run demo:build:
-- edit content/demo-stories/ and content/classics/texts/, never this file.
-- In the SQL Editor, run the parts in order, 01 first; each is its own transaction and safe to run twice.
-- The same top-up as one file, for psql: supabase/staging-topups/demo-content-2a.sql.
begin;

-- 1. Never production: the 16 seed personas exist only on local and staging databases.
do $$
begin
  if (select count(*) from auth.users where email like '%@personas.test') < 16 then
    raise exception 'This top-up is for local and staging databases only: the 16 seed personas are missing.';
  end if;
end;
$$;

-- The classics account's names are settings, not code (CLAUDE.md): change them here, not below.
insert into public.settings (key, value, is_public, description) values
  ('classics_account_handle', '"clasice"'::jsonb, true,
   'Handle of the official account that publishes public-domain classics (S1-E5-06, S1-E11-16; demo top-up 23 Oct 2026).'),
  ('classics_account_pen_name', '"Clasice"'::jsonb, true,
   'Pen name of the official classics account.')
on conflict (key) do nothing;

-- 2. The new synthetic writers and the classics account, created exactly as supabase/seed.sql
--    creates the personas (auth user, email identity, profile, consents). The one exception to
--    "top-ups never create accounts" (Robert, 23 Oct 2026, for this top-up only). An account
--    that already exists is skipped, so the file is safe to run twice.
do $$
declare
  current_year integer := extract(year from (now() at time zone 'Europe/Bucharest'))::integer;
  shared_password text := 'Persona-Test-2026!';
  writer record;
begin
  for writer in
    select * from (values
      ('00000000-0000-4000-8000-000000000101'::uuid, 'ana_cu_harti', 'Ana cu Hărți', 34),
      ('00000000-0000-4000-8000-000000000102'::uuid, 'tudor_farasomn', 'Tudor Fărăsomn', 41),
      ('00000000-0000-4000-8000-000000000103'::uuid, 'ilinca_noaptea', 'Ilinca Noaptea', 27),
      ('00000000-0000-4000-8000-000000000104'::uuid, 'radu_din_deal', 'Radu din Deal', 52),
      ('00000000-0000-4000-8000-000000000105'::uuid, 'sofia_cerneala', 'Sofia Cerneală', 23),
      ('00000000-0000-4000-8000-000000000100'::uuid, coalesce(public.setting_value('classics_account_handle') #>> '{}', 'clasice'), coalesce(public.setting_value('classics_account_pen_name') #>> '{}', 'Clasice'), 35)
    ) as writers (user_id, handle, pen_name, years_old)
  loop
    if exists (select 1 from auth.users where users.id = writer.user_id) then
      continue;
    end if;
    insert into auth.users (
      instance_id, id, aud, role, email, encrypted_password, email_confirmed_at,
      raw_app_meta_data, raw_user_meta_data, created_at, updated_at,
      confirmation_token, recovery_token, email_change_token_new, email_change
    ) values (
      '00000000-0000-0000-0000-000000000000', writer.user_id, 'authenticated', 'authenticated',
      writer.handle || '@personas.test',
      extensions.crypt(shared_password, extensions.gen_salt('bf')), now(),
      '{"provider": "email", "providers": ["email"], "seed_persona": true}', '{}', now(), now(),
      '', '', '', ''
    );
    insert into auth.identities (provider_id, user_id, identity_data, provider, created_at, updated_at)
    values (
      writer.user_id::text, writer.user_id,
      jsonb_build_object('sub', writer.user_id::text, 'email', writer.handle || '@personas.test', 'email_verified', true),
      'email', now(), now()
    );
    -- Adults with a passed check, like adult_writer, so the account gate lets them publish.
    insert into public.profiles (id, birth_year, age_check_result, age_checked_at, age_check_method, handle, pen_name)
    values (writer.user_id, current_year - writer.years_old, '18_or_over', now(), 'facial_estimation', writer.handle, writer.pen_name);
    insert into public.consents (user_id, legal_document_version_id, method)
    select writer.user_id, versions.id, 'sign_up'
    from public.legal_document_versions as versions
    join public.legal_documents as documents on documents.id = versions.document_id
    where documents.needs_acceptance and versions.version_label = '0.1' and versions.language = 'en';
  end loop;
end;
$$;


-- demo-01: "Pâinea de duminică" by adult_writer
insert into public.stories (id, user_id, slug, title, blurb, language_code, category_id,
  cover_kind, cover_design, cover_background, cover_accent, rating, ai_disclosure,
  first_published_at, last_chapter_published_at, created_at)
select '00000000-0000-4000-9100-000100000000'::uuid, '00000000-0000-4000-8000-000000000001'::uuid, 'painea-de-duminica-demo-01',
  $demo$Pâinea de duminică$demo$, $demo$Irina se întoarce în orașul în care a crescut ca să țină brutăria tatălui ei o singură săptămână. Rețetele sunt toate în caiet, în afară de una: pâinea pe care o coace el doar duminica, pe care nu o vinde nimănui. Și tata nu vrea să-i spună de ce.$demo$, 'ro',
  (select id from public.categories where slug = 'fiction'),
  'drawn', 'paper', 'gold', 'plum', 'all_ages', 'no_ai',
  now() - interval '38 days', now() - interval '32 days', now() - interval '40 days'
where not exists (select 1 from public.stories where stories.id = '00000000-0000-4000-9100-000100000000'::uuid);
select public.set_story_tags('00000000-0000-4000-9100-000100000000'::uuid, '00000000-0000-4000-8000-000000000001'::uuid, array['familie', 'brutărie', 'oraș mic', 'întoarcere acasă']);
insert into public.chapters (id, story_id, user_id, code, position, draft_title, draft_body, draft_version,
  draft_saved_at, published_title, published_body, status, first_published_at, last_published_at, word_count,
  published_word_count, created_at)
select '00000000-0000-4000-9100-000100010000'::uuid, '00000000-0000-4000-9100-000100000000'::uuid, '00000000-0000-4000-8000-000000000001'::uuid,
  'd001c001', 1, $demo$Capitolul 1: Cheia de sub ghiveci$demo$, public.check_chapter_text($demo$Irina a găsit cheia exact unde îi spusese tata la telefon: sub ghiveciul cu mușcate de lângă ușa din spate, învelită într-o pungă de plastic ca să nu ruginească. Trecuseră doisprezece ani de când plecase din Târgu Vechi, și ghiveciul era același. Mușcatele, probabil, nu.

Brutăria mirosea a drojdie și a lemn vechi, chiar și cu cuptorul rece. Pe peretele din stânga stătea încă tabla pe care tata scria prețurile cu cretă, iar sub ea, pe un cui, atârna șorțul lui alb, cu o pată de cafea în colț pe care Irina o ținea minte din copilărie. Îi venea să râdă și să plângă în același timp, așa că a făcut ce făcea întotdeauna când nu știa ce să facă: a pus apa la fiert.

Tata era la spital, la oraș, cu piciorul în ghips, după ce căzuse de pe scara din magazie.

„Doar o săptămână", îi spusese. „Oamenii s-au obișnuit cu pâinea noastră. Dacă închid o săptămână, se duc la supermarket și nu se mai întorc."

„Tată, eu lucrez într-un birou. Eu știu să fac tabele."

„Și pâinea e un tabel. Făină, apă, sare, drojdie, timp. Totul e scris în caiet."

Caietul era în sertarul de sub tejghea, gros, cu coperțile legate cu bandă adezivă. Irina l-a răsfoit stând în picioare. Pâine albă. Pâine cu cartofi. Chifle cu susan. Cozonac de Paște, cu nota „nu te grăbi la a doua dospire, că te râde toată strada". Fiecare rețetă avea cantitățile scrise mărunt și câte o observație a tatei pe margine, cu alt pix, din alt an.

A ajuns la ultima pagină scrisă. „Pâinea de duminică." Dedesubt, nimic. Pagina era goală, cu excepția unui desen mic, un cerc cu o cruce pe el, așa cum se crestează pâinea înainte să intre în cuptor.

Irina a stat mult cu pagina aceea în față. Toată copilăria ei, duminica dimineață, tata se trezea la patru și cocea o pâine rotundă, grea, cu coaja crăpată, pe care nu o vindea niciodată. O tăia la masă, după biserică, și împărțea feliile în ordine: mama, bunica, Irina, el. Nu îl întrebase nimeni din ce era făcută. Era, simplu, pâinea de duminică.

Telefonul a sunat. Tata.

„Ai găsit cheia?"

„Am găsit și caietul. Tată, la pâinea de duminică nu e scris nimic."

Pauză. Pe fundal se auzea un televizor și cineva care râdea.

„Nu e nevoie. Nu o vinzi."

„Dar o faci în fiecare duminică."

„Eu o fac. Tu te ocupi de restul. Pune drojdia la frigider și culcă-te, că mâine la cinci ești la cuptor."

Și a închis, așa cum închidea el, fără la revedere, dar fără supărare.$demo$), 1,
  now() - interval '38 days', $demo$Capitolul 1: Cheia de sub ghiveci$demo$, public.check_chapter_text($demo$Irina a găsit cheia exact unde îi spusese tata la telefon: sub ghiveciul cu mușcate de lângă ușa din spate, învelită într-o pungă de plastic ca să nu ruginească. Trecuseră doisprezece ani de când plecase din Târgu Vechi, și ghiveciul era același. Mușcatele, probabil, nu.

