-- demo-02: "Ce rămâne într-o casă goală" by adult_writer
insert into public.stories (id, user_id, slug, title, blurb, language_code, category_id,
  cover_kind, cover_design, cover_background, cover_accent, rating, ai_disclosure,
  first_published_at, last_chapter_published_at, created_at)
select '00000000-0000-4000-9100-000200000000'::uuid, '00000000-0000-4000-8000-000000000001'::uuid, 'ce-ramane-intr-o-casa-goala-demo-02',
  $demo$Ce rămâne într-o casă goală$demo$, $demo$Când bunica mea a murit, am avut trei zile ca să golesc o casă în care trăise șaizeci de ani. Un eseu despre ce păstrezi, ce arunci și ce rămâne oricum în pereți, orice ai face.$demo$, 'ro',
  (select id from public.categories where slug = 'nonfiction_essays'),
  'automatic', null, null, null, '13_plus', 'no_ai',
  now() - interval '75 days', now() - interval '69 days', now() - interval '77 days'
where not exists (select 1 from public.stories where stories.id = '00000000-0000-4000-9100-000200000000'::uuid);
select public.set_story_tags('00000000-0000-4000-9100-000200000000'::uuid, '00000000-0000-4000-8000-000000000001'::uuid, array['eseu', 'bunici', 'amintiri', 'doliu', 'casă']);
insert into public.chapters (id, story_id, user_id, code, position, draft_title, draft_body, draft_version,
  draft_saved_at, published_title, published_body, status, first_published_at, last_published_at, word_count,
  published_word_count, created_at)
select '00000000-0000-4000-9100-000200010000'::uuid, '00000000-0000-4000-9100-000200000000'::uuid, '00000000-0000-4000-8000-000000000001'::uuid,
  'd002c001', 1, $demo$Capitolul 1: Trei zile$demo$, public.check_chapter_text($demo$Casa bunicii mele trebuia golită în trei zile, pentru că atât ne dăduse omul care o cumpărase, un bărbat politicos și grăbit, care voia să înceapă renovarea luni. Am ajuns vineri seara, cu mama, cu o mașină împrumutată și cu o listă pe care scrisesem lucrurile de luat: actele, fotografiile, mașina de cusut, icoana de la fereastră.

Lista a durat o oră. Casa a durat trei zile.

Prima problemă cu o casă în care cineva a trăit șaizeci de ani este că nu există nimic lipsit de importanță. Am deschis un sertar din bucătărie și am găsit capace de borcane, așezate pe mărimi, puse unele peste altele, cu o răbdare pe care nu o mai văd la nimeni. Nu poți arunca așa ceva fără să te simți ca un om prost crescut. Dar nici nu le poți lua. Ce faci cu patruzeci de capace de borcan într-un apartament de două camere la oraș?

Mama a tranșat problema cu metoda ei: a răsturnat sertarul într-un sac fără să se uite. Eu am stat cu un capac în mână două minute. Era albastru, de la un compot de vișine pe care îl ținem minte amândouă, și m-am gândit că bunica l-a spălat și l-a pus acolo cu mâna ei, într-o zi oarecare, fără să bănuiască că o să fie ultimul lucru pe care îl ating din ea.

Pe urmă l-am aruncat. Nu există alt sfârșit pentru propoziția asta.

A doua problemă e că obiectele vorbesc numai cât timp le ții în casă. Mașina de cusut, scoasă în curte și pusă lângă mașină, a devenit instantaneu un obiect greu, vechi și verde, care nu mai avea nimic de spus. În casă, lângă fereastră, cu pedala tocită în locul în care piciorul bunicii se așezase o jumătate de secol, era bunica. În curte era fier.

Am luat-o oricum. Stă acum în camera mea, lângă birou, și n-am cusut la ea niciodată. Mama zice că e un cuier scump. Are dreptate și nu are.

În prima seară am dormit în patul bunicii, pentru că celălalt pat era deja demontat. Așternuturile miroseau a săpunul ei, unul ieftin, de la magazinul din sat, și am stat trează până târziu, ascultând casa. Casele vechi au sunete pe care nu le auzi decât când sunt aproape goale: o scândură care se întinde, țiglele care se răcesc, frigiderul care pornește și se oprește ca un om care își drege vocea și nu mai zice nimic.$demo$), 1,
  now() - interval '75 days', $demo$Capitolul 1: Trei zile$demo$, public.check_chapter_text($demo$Casa bunicii mele trebuia golită în trei zile, pentru că atât ne dăduse omul care o cumpărase, un bărbat politicos și grăbit, care voia să înceapă renovarea luni. Am ajuns vineri seara, cu mama, cu o mașină împrumutată și cu o listă pe care scrisesem lucrurile de luat: actele, fotografiile, mașina de cusut, icoana de la fereastră.

Lista a durat o oră. Casa a durat trei zile.

Prima problemă cu o casă în care cineva a trăit șaizeci de ani este că nu există nimic lipsit de importanță. Am deschis un sertar din bucătărie și am găsit capace de borcane, așezate pe mărimi, puse unele peste altele, cu o răbdare pe care nu o mai văd la nimeni. Nu poți arunca așa ceva fără să te simți ca un om prost crescut. Dar nici nu le poți lua. Ce faci cu patruzeci de capace de borcan într-un apartament de două camere la oraș?

Mama a tranșat problema cu metoda ei: a răsturnat sertarul într-un sac fără să se uite. Eu am stat cu un capac în mână două minute. Era albastru, de la un compot de vișine pe care îl ținem minte amândouă, și m-am gândit că bunica l-a spălat și l-a pus acolo cu mâna ei, într-o zi oarecare, fără să bănuiască că o să fie ultimul lucru pe care îl ating din ea.

Pe urmă l-am aruncat. Nu există alt sfârșit pentru propoziția asta.

A doua problemă e că obiectele vorbesc numai cât timp le ții în casă. Mașina de cusut, scoasă în curte și pusă lângă mașină, a devenit instantaneu un obiect greu, vechi și verde, care nu mai avea nimic de spus. În casă, lângă fereastră, cu pedala tocită în locul în care piciorul bunicii se așezase o jumătate de secol, era bunica. În curte era fier.

Am luat-o oricum. Stă acum în camera mea, lângă birou, și n-am cusut la ea niciodată. Mama zice că e un cuier scump. Are dreptate și nu are.

În prima seară am dormit în patul bunicii, pentru că celălalt pat era deja demontat. Așternuturile miroseau a săpunul ei, unul ieftin, de la magazinul din sat, și am stat trează până târziu, ascultând casa. Casele vechi au sunete pe care nu le auzi decât când sunt aproape goale: o scândură care se întinde, țiglele care se răcesc, frigiderul care pornește și se oprește ca un om care își drege vocea și nu mai zice nimic.$demo$), 'published',
  now() - interval '75 days', now() - interval '75 days', public.count_words($demo$Casa bunicii mele trebuia golită în trei zile, pentru că atât ne dăduse omul care o cumpărase, un bărbat politicos și grăbit, care voia să înceapă renovarea luni. Am ajuns vineri seara, cu mama, cu o mașină împrumutată și cu o listă pe care scrisesem lucrurile de luat: actele, fotografiile, mașina de cusut, icoana de la fereastră.

