-- demo-03: "Apa a venit noaptea" by adult_writer
insert into public.stories (id, user_id, slug, title, blurb, language_code, category_id,
  cover_kind, cover_design, cover_background, cover_accent, rating, ai_disclosure,
  first_published_at, last_chapter_published_at, created_at)
select '00000000-0000-4000-9100-000300000000'::uuid, '00000000-0000-4000-8000-000000000001'::uuid, 'apa-a-venit-noaptea-demo-03',
  $demo$Apa a venit noaptea$demo$, $demo$Într-o noapte de iunie, râul iese din matcă și înghite jumătate din Valea Largă. Matei are nouăsprezece ani, lanterna unui telefon și o soră pe care nu o găsește nicăieri. O poveste despre o noapte, o salcie și ce rămâne după ce apa se retrage.$demo$, 'ro',
  (select id from public.categories where slug = 'fiction'),
  'automatic', null, null, null, '16_plus', 'no_ai',
  now() - interval '22 days', now() - interval '13 days', now() - interval '24 days'
where not exists (select 1 from public.stories where stories.id = '00000000-0000-4000-9100-000300000000'::uuid);
select public.set_story_tags('00000000-0000-4000-9100-000300000000'::uuid, '00000000-0000-4000-8000-000000000001'::uuid, array['inundație', 'frați', 'sat', 'pierdere', 'curaj']);
insert into public.chapters (id, story_id, user_id, code, position, draft_title, draft_body, draft_version,
  draft_saved_at, published_title, published_body, status, first_published_at, last_published_at, word_count,
  published_word_count, created_at)
select '00000000-0000-4000-9100-000300010000'::uuid, '00000000-0000-4000-9100-000300000000'::uuid, '00000000-0000-4000-8000-000000000001'::uuid,
  'd003c001', 1, $demo$Capitolul 1: Zgomotul$demo$, public.check_chapter_text($demo$Matei s-a trezit pentru că nu mai auzea râul. Îl auzise toată seara, umflat de trei zile de ploaie, un vuiet continuu care intrase în casă ca o rudă nepoftită. Și acum, la două și ceva noaptea, nu mai era vuiet. Era altceva. Un sunet gros, apropiat, ca și cum cineva ar fi tras cu un camion pe sub ferestre.

A pus piciorul jos din pat și apa i-a venit până la gleznă.

„Dana!" a strigat, și vocea i-a sunat străin. „Dana, mamă, treziți-vă!"

Mama a apărut în ușă cu telefonul în mână, lumina ecranului tremurând pe perete. Apa era deja la genunchi și urca atât de repede încât o vedeai urcând, ca într-un film dat mai iute. Pe hol plutea un papuc. Frigiderul s-a prăbușit pe o parte cu un pocnet surd.

„Unde e Dana?"

„În camera ei, dormea…"

Camera Danei era goală. Patul desfăcut, fereastra deschisă, perdeaua umflată de vânt și de ploaie. Pe pervaz, o urmă de noroi. Matei a înțeles în aceeași clipă două lucruri: că sora lui de cincisprezece ani ieșise pe fereastră, și că n-avea cum s-o întrebe de ce.

„A ieșit", a zis. „A ieșit la Luca, probabil, la ai lui, ei stau mai sus."

„Nu știi asta."

„Nu știu nimic, mamă, hai!"

Au urcat în pod pe scara de lemn, cu apa venind după ei treaptă cu treaptă, și de la lucarnă au văzut Valea Largă așa cum n-o văzuse nimeni, nici bătrânii care povesteau de inundația din '70. Nu mai era o vale. Era un lac negru, lat, cu acoperișuri în el, și pe suprafața lui curgeau lucruri: un gard întreg, un butoi, ceva alb și mare care s-a dovedit a fi frigiderul familiei Ardelean. Luminile de la stâlpi se stinseseră. Singura lumină era lanterna telefonului mamei și, departe, la deal, farurile unei mașini care claxona continuu, de parcă asta ar fi ajutat la ceva.

„Ia telefonul", a zis mama. „Sună la 112."

Matei a sunat. O voce calmă i-a cerut adresa și i-a spus să nu intre în apă. El a râs, scurt, urât, și a închis.

Apoi a coborât două trepte, până unde apa îi ajungea la piept, și s-a uitat spre fereastra Danei, care nu se mai vedea.

„Nu", a zis mama.

„Stau aici, pe scară. Nu intru nicăieri. Doar mă uit."

Minciuna a durat până la prima lumină.$demo$), 1,
