-- demo-05: "Tramvaiul zero" by ana_cu_harti
insert into public.stories (id, user_id, slug, title, blurb, language_code, category_id,
  cover_kind, cover_design, cover_background, cover_accent, rating, ai_disclosure,
  first_published_at, last_chapter_published_at, created_at)
select '00000000-0000-4000-9100-000500000000'::uuid, '00000000-0000-4000-8000-000000000101'::uuid, 'tramvaiul-zero-demo-05',
  $demo$Tramvaiul zero$demo$, $demo$În căptușeala unui palton de la talcioc, Sara găsește o hartă a liniilor de tramvai din oraș. Toate sunt cele știute, în afară de una: linia 0, care oprește doar când plouă. Sara îl convinge pe Vlad, colegul care nu vorbește niciodată la ore, să aștepte cu ea în stație. Tramvaiul vine. Și duce exact în locurile pe care orașul le-a pierdut.$demo$, 'ro',
  (select id from public.categories where slug = 'fiction'),
  'automatic', null, null, null, '13_plus', 'no_ai',
  now() - interval '6 days', now() - interval '1 days', now() - interval '8 days'
where not exists (select 1 from public.stories where stories.id = '00000000-0000-4000-9100-000500000000'::uuid);
select public.set_story_tags('00000000-0000-4000-9100-000500000000'::uuid, '00000000-0000-4000-8000-000000000101'::uuid, array['tramvai', 'hărți', 'prietenie', 'oraș', 'mister']);
insert into public.chapters (id, story_id, user_id, code, position, draft_title, draft_body, draft_version,
  draft_saved_at, published_title, published_body, status, first_published_at, last_published_at, word_count,
  published_word_count, created_at)
select '00000000-0000-4000-9100-000500010000'::uuid, '00000000-0000-4000-9100-000500000000'::uuid, '00000000-0000-4000-8000-000000000101'::uuid,
  'd005c001', 1, $demo$Capitolul 1: Căptușeala$demo$, public.check_chapter_text($demo$Paltonul costa cincisprezece lei la talciocul de lângă podul de fier și mirosea a naftalină și a ploaie veche. Sara l-a luat pentru că era verde închis, de culoarea sticlelor de sirop, și pentru că avea nasturi de os pe care nu-i mai făcea nimeni. Mama a zis că arată ca un palton de bunică. Sara a zis că exact asta era ideea.

Harta a găsit-o abia seara, când a încercat să coasă o gaură din buzunar. Degetele au dat peste ceva tare sub căptușeală, un pătrat împăturit de mai multe ori. L-a scos cu foarfeca de unghii, încet, ca pe o așchie.

Era o hartă a orașului desenată de mână, cu tuș albastru, pe hârtie de calc îngălbenită. Nu avea străzi, avea doar liniile de tramvai, fiecare cu altă culoare și cu numărul scris într-un cerc. Sara le știa pe toate. Cu 3 mergea la școală. Cu 11 la bunica. Cu 7 nu mergea nimeni dacă nu era obligat.

Mai era una. O linie subțire, cu creionul, care pornea din stația de lângă bazinul vechi, ocolea tot orașul și se termina într-un punct fără nume. Lângă ea, în cerc, era scris: 0. Și dedesubt, cu litere mici, înclinate: „Doar când plouă. Nu cobori la capăt.”

A doua zi a dus harta la școală. Nu știa de ce. Poate pentru că nu avea cui s-o arate acasă. La ora de geografie, Vlad Mitrea, care stătea în banca din fața ei și nu vorbise de bunăvoie din clasa a cincea, s-a întors să-i dea fișele și a rămas cu ochii pe hârtia de calc.

— De unde ai aia?

Era cea mai lungă frază pe care i-o spusese vreodată.

— Dintr-un palton.

— Linia zero, a zis Vlad, și a atins cercul cu vârful degetului, ca și cum ar fi putut să se ude. Bunicul meu povestea de ea. Zicea că a mers cu ea o dată, când era mic, și că n-a mai vrut să meargă niciodată.

— De ce?

Vlad a ridicat din umeri.

— Zicea că te duce unde nu mai e nimic. Și că e cel mai frumos loc din oraș.

Profesoara a tușit apăsat. Vlad s-a întors cu fața la tablă, dar Sara i-a văzut urechile, roșii până în vârf.

Joi a început să plouă la patru după-amiaza. Ploaie măruntă, încăpățânată, de octombrie. Sara a luat paltonul verde și s-a dus la stația de lângă bazinul vechi, unde nu mai oprea nimic de ani de zile. Vlad era deja acolo, cu gluga trasă pe ochi, și s-a prefăcut că e acolo din întâmplare.

Au așteptat douăzeci de minute fără să vorbească. Apoi, de după colț, cu un scârțâit lung și cu geamurile aburite, a apărut un tramvai galben, vechi, cu un singur vagon. Pe plăcuța din față scria 0.$demo$), 1,
  now() - interval '6 days', $demo$Capitolul 1: Căptușeala$demo$, public.check_chapter_text($demo$Paltonul costa cincisprezece lei la talciocul de lângă podul de fier și mirosea a naftalină și a ploaie veche. Sara l-a luat pentru că era verde închis, de culoarea sticlelor de sirop, și pentru că avea nasturi de os pe care nu-i mai făcea nimeni. Mama a zis că arată ca un palton de bunică. Sara a zis că exact asta era ideea.

Harta a găsit-o abia seara, când a încercat să coasă o gaură din buzunar. Degetele au dat peste ceva tare sub căptușeală, un pătrat împăturit de mai multe ori. L-a scos cu foarfeca de unghii, încet, ca pe o așchie.

Era o hartă a orașului desenată de mână, cu tuș albastru, pe hârtie de calc îngălbenită. Nu avea străzi, avea doar liniile de tramvai, fiecare cu altă culoare și cu numărul scris într-un cerc. Sara le știa pe toate. Cu 3 mergea la școală. Cu 11 la bunica. Cu 7 nu mergea nimeni dacă nu era obligat.

Mai era una. O linie subțire, cu creionul, care pornea din stația de lângă bazinul vechi, ocolea tot orașul și se termina într-un punct fără nume. Lângă ea, în cerc, era scris: 0. Și dedesubt, cu litere mici, înclinate: „Doar când plouă. Nu cobori la capăt.”

A doua zi a dus harta la școală. Nu știa de ce. Poate pentru că nu avea cui s-o arate acasă. La ora de geografie, Vlad Mitrea, care stătea în banca din fața ei și nu vorbise de bunăvoie din clasa a cincea, s-a întors să-i dea fișele și a rămas cu ochii pe hârtia de calc.

— De unde ai aia?

Era cea mai lungă frază pe care i-o spusese vreodată.

— Dintr-un palton.

— Linia zero, a zis Vlad, și a atins cercul cu vârful degetului, ca și cum ar fi putut să se ude. Bunicul meu povestea de ea. Zicea că a mers cu ea o dată, când era mic, și că n-a mai vrut să meargă niciodată.

— De ce?

Vlad a ridicat din umeri.

— Zicea că te duce unde nu mai e nimic. Și că e cel mai frumos loc din oraș.

Profesoara a tușit apăsat. Vlad s-a întors cu fața la tablă, dar Sara i-a văzut urechile, roșii până în vârf.

Joi a început să plouă la patru după-amiaza. Ploaie măruntă, încăpățânată, de octombrie. Sara a luat paltonul verde și s-a dus la stația de lângă bazinul vechi, unde nu mai oprea nimic de ani de zile. Vlad era deja acolo, cu gluga trasă pe ochi, și s-a prefăcut că e acolo din întâmplare.

Au așteptat douăzeci de minute fără să vorbească. Apoi, de după colț, cu un scârțâit lung și cu geamurile aburite, a apărut un tramvai galben, vechi, cu un singur vagon. Pe plăcuța din față scria 0.$demo$), 'published',
