where not exists (select 1 from public.chapters where chapters.id = '00000000-0000-4000-9100-000500030000'::uuid);

-- demo-06: "Strada care se mută marțea" by ana_cu_harti
insert into public.stories (id, user_id, slug, title, blurb, language_code, category_id,
  cover_kind, cover_design, cover_background, cover_accent, rating, ai_disclosure,
  first_published_at, last_chapter_published_at, created_at)
select '00000000-0000-4000-9100-000600000000'::uuid, '00000000-0000-4000-8000-000000000101'::uuid, 'strada-care-se-muta-martea-demo-06',
  $demo$Strada care se mută marțea$demo$, $demo$Iris locuiește pe strada Pelinului, care în fiecare marți se mută în alt colț al orașului, cu case, copaci și cutii poștale cu tot. Poștașul Grigore are o hartă specială ca să o găsească. Dar într-o marți strada se blochează între două bulevarde, harta lui Grigore se udă, iar motanul Pufoaica dispare. Iris trebuie să deseneze ea drumul spre casă.$demo$, 'ro',
  (select id from public.categories where slug = 'fiction'),
  'drawn', 'dots', 'lilac', 'gold', 'all_ages', 'no_ai',
  now() - interval '43 days', now() - interval '37 days', now() - interval '45 days'
where not exists (select 1 from public.stories where stories.id = '00000000-0000-4000-9100-000600000000'::uuid);
select public.set_story_tags('00000000-0000-4000-9100-000600000000'::uuid, '00000000-0000-4000-8000-000000000101'::uuid, array['copii', 'stradă', 'hărți', 'pisici', 'aventură']);
insert into public.chapters (id, story_id, user_id, code, position, draft_title, draft_body, draft_version,
  draft_saved_at, published_title, published_body, status, first_published_at, last_published_at, word_count,
  published_word_count, created_at)
select '00000000-0000-4000-9100-000600010000'::uuid, '00000000-0000-4000-9100-000600000000'::uuid, '00000000-0000-4000-8000-000000000101'::uuid,
  'd006c001', 1, $demo$Capitolul 1: Marțea pe strada Pelinului$demo$, public.check_chapter_text($demo$Pe strada Pelinului erau unsprezece case, un tei bătrân, o fântână cu cumpănă care nu mai scotea apă și o cutie poștală roșie, strâmbă, care stătea în colț de când se știa lumea. Și, în fiecare marți, strada se muta.

Nu se muta departe. Nu pleca din oraș. Doar se ridica ușor, ca un covor scuturat, în noaptea de luni spre marți, și se așeza altundeva. Uneori lângă gară. Alteori în spatele pieței de flori. O dată ajunsese chiar lângă grădina zoologică, și toată ziua copiii de pe stradă se uitaseră pe gard la o girafă care se uita și ea la ei.

Iris avea nouă ani și locuia la numărul 4, cu mama, cu bunicul Vasile și cu motanul Pufoaica, care era gri, gras și nu pricepea de ce marțea mirosul de afară era mereu altul.

— Unde suntem azi? întreba Iris la micul dejun, în fiecare marți.

Bunicul ridica perdeaua și se uita afară cu ochii mijiți.

— Hm. Văd un turn cu ceas. Văd un chioșc cu covrigi. Cred că suntem lângă piața mare.

— Atunci azi iau covrigi la școală!

Școala nu se muta niciodată, din păcate, așa că marțea Iris trebuia să găsească drumul până la ea de fiecare dată din alt loc. Dar nu se rătăcea niciodată, pentru că pe strada Pelinului venea, în fiecare marți la ora opt fix, domnul Grigore, poștașul.

Domnul Grigore era lung și subțire, cu o mustață ca o perie de pantofi și o geantă de piele mai veche decât el. În geantă avea scrisorile, ziarele și harta. Harta era desenată pe o foaie mare de hârtie groasă și avea pe ea toate străzile orașului. Strada Pelinului era desenată cu cerneală verde și se mișca singură pe hârtie, în fiecare luni noaptea, așa că domnul Grigore o găsea mereu.

— Bună dimineața, domnișoară Iris, spunea el, și ducea mâna la șapcă. Azi suntem în spatele bibliotecii. Drumul spre școală e pe aici, la stânga, apoi drept, pe lângă statuia cu porumbei.

Și desena cu degetul, pe hartă, drumul, ca să-l țină ea minte.

Iris îl iubea pe domnul Grigore aproape la fel de mult ca pe Pufoaica. Și visa ca într-o zi să aibă și ea o hartă la fel.

Într-o luni seara, când s-a dus la culcare, Iris a auzit vântul bătând mai tare ca de obicei. Teiul scârțâia. Fântâna scotea un sunet ciudat, ca un fluier. Iar Pufoaica, care dormea mereu la picioarele ei, s-a ridicat, s-a uitat pe geam cu coada umflată și a ieșit din cameră.

Iris a vrut să se ducă după el. Dar patul era cald și pleoapele grele, așa că a adormit.$demo$), 1,
