-- demo-08: "Dovleacul lui nea Gogu" by radu_din_deal
insert into public.stories (id, user_id, slug, title, blurb, language_code, category_id,
  cover_kind, cover_design, cover_background, cover_accent, rating, ai_disclosure,
  first_published_at, last_chapter_published_at, created_at)
select '00000000-0000-4000-9100-000800000000'::uuid, '00000000-0000-4000-8000-000000000104'::uuid, 'dovleacul-lui-nea-gogu-demo-08',
  $demo$Dovleacul lui nea Gogu$demo$, $demo$De douăzeci și doi de ani, nea Gogu și nea Pătru se ceartă pe un singur lucru: al cui dovleac e mai mare la Târgul de Toamnă din Valea Rățoiului. Anul ăsta, nea Gogu are un secret, iar dovleacul lui crește cât o căruță. Problema e că satul e pe deal. Și un dovleac cât o căruță nu stă pe deal dacă nu vrea el.$demo$, 'ro',
  (select id from public.categories where slug = 'fiction'),
  'automatic', null, null, null, 'all_ages', 'no_ai',
  now() - interval '27 days', now() - interval '21 days', now() - interval '29 days'
where not exists (select 1 from public.stories where stories.id = '00000000-0000-4000-9100-000800000000'::uuid);
select public.set_story_tags('00000000-0000-4000-9100-000800000000'::uuid, '00000000-0000-4000-8000-000000000104'::uuid, array['sat', 'umor', 'vecini', 'dovleci', 'toamnă']);
insert into public.chapters (id, story_id, user_id, code, position, draft_title, draft_body, draft_version,
  draft_saved_at, published_title, published_body, status, first_published_at, last_published_at, word_count,
  published_word_count, created_at)
select '00000000-0000-4000-9100-000800010000'::uuid, '00000000-0000-4000-9100-000800000000'::uuid, '00000000-0000-4000-8000-000000000104'::uuid,
  'd008c001', 1, $demo$Capitolul 1: Douăzeci și doi de ani de dovleci$demo$, public.check_chapter_text($demo$În Valea Rățoiului sunt două lucruri sigure în fiecare toamnă: că plouă exact în ziua culesului și că nea Gogu și nea Pătru nu-și vorbesc din august până în octombrie.

Ei sunt vecini, gard în gard, de când s-au născut. Au mers împreună la școală, au furat împreună cireșe de la popă, au fost cavaleri de onoare unul la nunta celuilalt. În restul anului beau cafeaua împreună pe banca de la poartă și se plâng împreună de guvern. Dar din august până în octombrie sunt dușmani de moarte, pentru că din august până în octombrie cresc dovlecii.

Totul a început acum douăzeci și doi de ani, la primul Târg de Toamnă organizat de primărie. S-a făcut atunci un concurs pentru cel mai mare dovleac din sat. A câștigat nea Pătru, cu un dovleac de patruzeci și unu de kilograme. Nea Gogu a ieșit al doilea, cu patruzeci de kilograme și nouă sute de grame. A cerut să se cântărească din nou. S-a cântărit din nou. Tot nouă sute de grame. De atunci nu l-a mai iertat nimeni pe cântar, nici pe nea Pătru.

De douăzeci și doi de ani, deci, se întrec. Când câștigă unul, când celălalt. Au încercat de toate. Nea Pătru a pus gunoi de cal adus special de la herghelie, din județul vecin. Nea Gogu a pus un difuzor în grădină și i-a cântat dovleacului muzică populară, zi și noapte, până s-a plâns satul. Nea Pătru a făcut o umbrelă mare din folie ca să nu-l bată soarele prea tare. Nea Gogu a dormit trei nopți în grădină, ca să nu i-l fure nimeni.

Eu îi cunosc pe amândoi bine, că stau peste drum. Și anul ăsta am văzut ceva ce nu mai văzusem.

Era pe la jumătatea lui august. M-am trezit în zori, să duc vaca la cireadă, și l-am văzut pe nea Gogu în grădină, în pijama, cu o găleată în mână, mergând pe vârfuri. S-a uitat în stânga și-n dreapta, nu m-a văzut, s-a aplecat peste dovleac și a început să-i toarne ceva alb la rădăcină.

— Nea Gogule, am zis eu peste gard, ce-i dai acolo?

A sărit în sus de parcă l-ar fi mușcat o viespe. A pus găleata la spate.

— Nimic. Apă.

— Apă albă?

— Apă de la izvor. E mai calcaroasă.

Nu l-am crezut. Dar nici nu l-am întrebat mai departe. Pe nea Gogu, dacă îl întrebi de două ori, se supără și nu-ți mai dă struguri la toamnă.

Până la sfârșitul lui septembrie, dovleacul lui nea Gogu era cât o roabă. La începutul lui octombrie, era cât o căruță. Copiii veneau să se uite la el pe gard, ca la circ. Nea Pătru se uita și el, de la fereastră, și nu mai ieșea la cafea nici dimineața.$demo$), 1,
  now() - interval '27 days', $demo$Capitolul 1: Douăzeci și doi de ani de dovleci$demo$, public.check_chapter_text($demo$În Valea Rățoiului sunt două lucruri sigure în fiecare toamnă: că plouă exact în ziua culesului și că nea Gogu și nea Pătru nu-și vorbesc din august până în octombrie.

Ei sunt vecini, gard în gard, de când s-au născut. Au mers împreună la școală, au furat împreună cireșe de la popă, au fost cavaleri de onoare unul la nunta celuilalt. În restul anului beau cafeaua împreună pe banca de la poartă și se plâng împreună de guvern. Dar din august până în octombrie sunt dușmani de moarte, pentru că din august până în octombrie cresc dovlecii.

Totul a început acum douăzeci și doi de ani, la primul Târg de Toamnă organizat de primărie. S-a făcut atunci un concurs pentru cel mai mare dovleac din sat. A câștigat nea Pătru, cu un dovleac de patruzeci și unu de kilograme. Nea Gogu a ieșit al doilea, cu patruzeci de kilograme și nouă sute de grame. A cerut să se cântărească din nou. S-a cântărit din nou. Tot nouă sute de grame. De atunci nu l-a mai iertat nimeni pe cântar, nici pe nea Pătru.

De douăzeci și doi de ani, deci, se întrec. Când câștigă unul, când celălalt. Au încercat de toate. Nea Pătru a pus gunoi de cal adus special de la herghelie, din județul vecin. Nea Gogu a pus un difuzor în grădină și i-a cântat dovleacului muzică populară, zi și noapte, până s-a plâns satul. Nea Pătru a făcut o umbrelă mare din folie ca să nu-l bată soarele prea tare. Nea Gogu a dormit trei nopți în grădină, ca să nu i-l fure nimeni.

Eu îi cunosc pe amândoi bine, că stau peste drum. Și anul ăsta am văzut ceva ce nu mai văzusem.

Era pe la jumătatea lui august. M-am trezit în zori, să duc vaca la cireadă, și l-am văzut pe nea Gogu în grădină, în pijama, cu o găleată în mână, mergând pe vârfuri. S-a uitat în stânga și-n dreapta, nu m-a văzut, s-a aplecat peste dovleac și a început să-i toarne ceva alb la rădăcină.

— Nea Gogule, am zis eu peste gard, ce-i dai acolo?

A sărit în sus de parcă l-ar fi mușcat o viespe. A pus găleata la spate.

— Nimic. Apă.

— Apă albă?

— Apă de la izvor. E mai calcaroasă.

Nu l-am crezut. Dar nici nu l-am întrebat mai departe. Pe nea Gogu, dacă îl întrebi de două ori, se supără și nu-ți mai dă struguri la toamnă.

Până la sfârșitul lui septembrie, dovleacul lui nea Gogu era cât o roabă. La începutul lui octombrie, era cât o căruță. Copiii veneau să se uite la el pe gard, ca la circ. Nea Pătru se uita și el, de la fereastră, și nu mai ieșea la cafea nici dimineața.$demo$), 'published',
  now() - interval '27 days', now() - interval '27 days', public.count_words($demo$În Valea Rățoiului sunt două lucruri sigure în fiecare toamnă: că plouă exact în ziua culesului și că nea Gogu și nea Pătru nu-și vorbesc din august până în octombrie.

