where not exists (select 1 from public.chapters where chapters.id = '00000000-0000-4000-9100-000800030000'::uuid);

-- demo-09: "Ciobanul fără umbră de pe Râpa Albă" by radu_din_deal
insert into public.stories (id, user_id, slug, title, blurb, language_code, category_id,
  cover_kind, cover_design, cover_background, cover_accent, rating, ai_disclosure,
  first_published_at, last_chapter_published_at, created_at)
select '00000000-0000-4000-9100-000900000000'::uuid, '00000000-0000-4000-8000-000000000104'::uuid, 'ciobanul-fara-umbra-de-pe-rapa-alba-demo-09',
  $demo$Ciobanul fără umbră de pe Râpa Albă$demo$, $demo$Matei își petrece vara la bunici, în Râpa Albă, unde nu e semnal și nici nimic de făcut. Copiii din sat îi spun de Ciobanul fără umbră, care umblă pe deal în noaptea de după primul fân și îi rătăcește pe cei care urcă. Lavinia îl provoacă să urce cu ea. Ceața vine mai repede decât credeau. Iar la stâna părăsită arde un felinar pe care nu l-a aprins nimeni.$demo$, 'ro',
  (select id from public.categories where slug = 'fiction'),
  'drawn', 'grid', 'sage', 'violet', '13_plus', 'no_ai',
  now() - interval '64 days', now() - interval '58 days', now() - interval '66 days'
where not exists (select 1 from public.stories where stories.id = '00000000-0000-4000-9100-000900000000'::uuid);
select public.set_story_tags('00000000-0000-4000-9100-000900000000'::uuid, '00000000-0000-4000-8000-000000000104'::uuid, array['sat', 'legendă', 'vară', 'ceață', 'prietenie', 'bunici']);
insert into public.chapters (id, story_id, user_id, code, position, draft_title, draft_body, draft_version,
  draft_saved_at, published_title, published_body, status, first_published_at, last_published_at, word_count,
  published_word_count, created_at)
select '00000000-0000-4000-9100-000900010000'::uuid, '00000000-0000-4000-9100-000900000000'::uuid, '00000000-0000-4000-8000-000000000104'::uuid,
  'd009c001', 1, $demo$Capitolul 1: Unde nu e semnal$demo$, public.check_chapter_text($demo$Primul lucru pe care l-a aflat Matei despre Râpa Albă a fost că telefonul lui avea acolo o singură liniuță de semnal, și doar dacă stătea în picioare pe capacul fântânii, cu mâna ridicată. Al doilea a fost că bunicul Toma se trezea la cinci și se aștepta ca toată lumea să facă la fel.

— La oraș dormi destul, zicea bunicul. Aici e vară.

Matei avea paisprezece ani și nu înțelegea legătura. Dar mânca la cinci și jumătate mămăligă cu brânză și smântână, ducea găinile afară, mergea cu bunicul la fân și seara, când se întuneca, nu mai era nimic de făcut decât să stea pe prispă și să se uite la deal.

Dealul era chiar în spatele satului, lung și pleșuv, cu o pădure de fagi pe coamă și cu o râpă de pământ alb pe o parte, de la care își luase satul numele. Sus, aproape de pădure, era o stână veche, cu acoperișul căzut pe jumătate.

— Acolo nu urci, a zis bunica Floarea din prima seară, fără să-l întrebe dacă voia. Râpa se surpă. Și nu e bine pe deal după primul fân.

— De ce nu e bine?

Bunica s-a uitat la bunicul. Bunicul a tușit și s-a dus să închidă poarta.

Matei a aflat de ce abia peste o săptămână, la podul de peste pârâu, unde se strângeau seara copiii din sat. Erau vreo șase, toți mai bronzați ca el și toți cu o părere despre orașeni. Cea mai gălăgioasă era Lavinia, nepoata vecinei, care avea tot paisprezece ani, părul tuns scurt de mâna ei și un fel de a se uita la el de parcă era o vacă nouă adusă în sat.

— Ție nu ți-au zis de Cioban? a întrebat ea.

— Ce cioban?

Copiii s-au uitat unii la alții, încântați.

Lavinia i-a povestit. Demult, zicea ea, un cioban de pe Râpa Albă era atât de leneș că, într-o noapte, și-a lăsat umbra să păzească oile în locul lui și s-a culcat. Umbra s-a înțeles așa de bine cu oile că n-a mai vrut să se întoarcă la el. Fără umbră, ciobanul n-a mai putut să coboare în sat, pentru că oamenii se speriau de el. Și a rămas sus, la stână, pentru totdeauna. În noaptea de după primul fân, când iarba e cosită și nu mai ai după ce să te ascunzi, el coboară până la râpă și îi cheamă pe cei care urcă. Cine îl urmează nu se mai întoarce.

— Și voi credeți asta?

— Noi nu, a zis Lavinia. Dar n-a urcat nimeni să vadă.

Bebe, vărul ei, de doisprezece ani, a fluierat lung și apăsat.

— Primul fân e mâine, a zis Lavinia. Dacă tot te plictisești.

Și s-a uitat la el cu un zâmbet strâmb pe care Matei avea să-l țină minte toată vara.$demo$), 1,
