-- demo-10: "Ultimul schimb de pe Stația Horia" by sofia_cerneala (Robert reads this one)
insert into public.stories (id, user_id, slug, title, blurb, language_code, category_id,
  cover_kind, cover_design, cover_background, cover_accent, rating, ai_disclosure,
  first_published_at, last_chapter_published_at, created_at)
select '00000000-0000-4000-9100-001000000000'::uuid, '00000000-0000-4000-8000-000000000105'::uuid, 'ultimul-schimb-de-pe-statia-horia-demo-10',
  $demo$Ultimul schimb de pe Stația Horia$demo$, $demo$Pe o stație orbitală pe care nimeni nu mai vrea s-o repare, Mara numără zilele până la naveta de retragere. Când oxigenul începe să scadă mai repede decât spun aparatele, află că cineva din echipaj a mințit de săptămâni. Și că naveta nu vine.$demo$, 'ro',
  (select id from public.categories where slug = 'fiction'),
  'drawn', 'starry', 'ink', 'gold', '16_plus', 'no_ai',
  now() - interval '11 days', now() - interval '5 days', now() - interval '13 days'
where not exists (select 1 from public.stories where stories.id = '00000000-0000-4000-9100-001000000000'::uuid);
select public.set_story_tags('00000000-0000-4000-9100-001000000000'::uuid, '00000000-0000-4000-8000-000000000105'::uuid, array['stație orbitală', 'oxigen', 'echipaj', 'minciună', 'supraviețuire']);
insert into public.chapters (id, story_id, user_id, code, position, draft_title, draft_body, draft_version,
  draft_saved_at, published_title, published_body, status, first_published_at, last_published_at, word_count,
  published_word_count, created_at)
select '00000000-0000-4000-9100-001000010000'::uuid, '00000000-0000-4000-9100-001000000000'::uuid, '00000000-0000-4000-8000-000000000105'::uuid,
  'd010c001', 1, $demo$Capitolul 1: Numărătoarea$demo$, public.check_chapter_text($demo$Pe Stația Horia, dimineața venea la fiecare nouăzeci de minute, așa că Mara învățase să n-o mai creadă. Dormea când îi spunea ceasul, mânca când îi spunea ceasul și, de patruzeci și una de zile, bifa în carnet câte zile mai sunt până la navetă. Scria cu pixul, pe hârtie, pentru că hârtia nu putea fi actualizată de la sol fără s-o întrebe nimeni.

Erau patru. Petre, comandantul, un om de cincizeci și ceva de ani care vorbea încet și se uita la tine ca și cum te-ar fi cântărit deja. Dinu, inginerul, care repara lucruri cu o răbdare aproape jignitoare. Ioana, medicul, care râdea rar și bine. Și Mara, tehnician de sisteme de viață, cea mai tânără, cea care știa exact cât aer respiră fiecare pe oră.

În dimineața aceea, falsă ca toate, a simțit în modulul de dormit un miros ciudat. Nu de ars. De închis. Ca o cameră în care ai ținut fereastra închisă o săptămână.

— Ai citirile la scrubere? l-a întrebat pe Petre la micul dejun.

— Le am. Nominal. Le am în fiecare zi, Mara.

— Senzorul meu portabil arată altceva.

— Senzorul tău portabil are doisprezece ani și a fost calibrat de un stagiar.

Dinu nu s-a uitat de la farfurie. Ioana a zâmbit scurt, cum zâmbești când nu vrei să fii băgată în discuție. Mara a tăcut. Pe Horia nu te certai la masă; masa era singurul loc unde nu se auzea ventilația.

După-amiaza s-a dus în modulul tehnic și a scos panoul de la scruberul doi cu mâinile ei. În interior, cartușele de absorbție erau cenușii la margini. Nu negre, nu încă. Cenușii. Mai aveau, după estimările ei, poate trei săptămâni la consumul normal. Naveta era în douăsprezece zile. Ar fi trebuit să fie bine.

Ar fi trebuit.

A pus panoul la loc, a scris în carnet „scruber 2: cenușiu, verifică la 48 h” și a rămas cu palma lipită de perete, acolo unde metalul era mereu un pic rece de la noaptea de afară. Sub palmă, stația vibra încet, egal, ca un animal mare care doarme.

Mara avea douăzeci și șase de ani. Semnase pentru opt luni și făcuse paisprezece, pentru că firma tot amânase retragerea și nimeni nu voia să plătească o navetă pentru patru oameni și o stație pe care urmau s-o lase să cadă în ocean. Știa toate astea. Ce nu știa încă era că, în dimineața aceea, dintre cei patru, trei mințeau. Doar că nu despre același lucru.$demo$), 1,
