-- demo-11: "Anul în care s-a oprit ploaia" by sofia_cerneala
insert into public.stories (id, user_id, slug, title, blurb, language_code, category_id,
  cover_kind, cover_design, cover_background, cover_accent, rating, ai_disclosure,
  first_published_at, last_chapter_published_at, created_at)
select '00000000-0000-4000-9100-001100000000'::uuid, '00000000-0000-4000-8000-000000000105'::uuid, 'anul-in-care-s-a-oprit-ploaia-demo-11',
  $demo$Anul în care s-a oprit ploaia$demo$, $demo$În Căluiești n-a mai plouat de paisprezece luni, iar stația meteo automată din turnul primăriei spune în fiecare dimineață același lucru. Teo are cincisprezece ani, o bunică care nu mai vrea să bea apa raționalizată și un băiat care lucrează la stația de desalinizare. Vara asta, învață că așteptarea e și ea o formă de curaj.$demo$, 'ro',
  (select id from public.categories where slug = 'fiction'),
  'automatic', null, null, null, '13_plus', 'no_ai',
  now() - interval '48 days', now() - interval '42 days', now() - interval '50 days'
where not exists (select 1 from public.stories where stories.id = '00000000-0000-4000-9100-001100000000'::uuid);
select public.set_story_tags('00000000-0000-4000-9100-001100000000'::uuid, '00000000-0000-4000-8000-000000000105'::uuid, array['secetă', 'adolescență', 'prima iubire', 'viitor apropiat', 'bunici']);
insert into public.chapters (id, story_id, user_id, code, position, draft_title, draft_body, draft_version,
  draft_saved_at, published_title, published_body, status, first_published_at, last_published_at, word_count,
  published_word_count, created_at)
select '00000000-0000-4000-9100-001100010000'::uuid, '00000000-0000-4000-9100-001100000000'::uuid, '00000000-0000-4000-8000-000000000105'::uuid,
  'd011c001', 1, $demo$Capitolul 1: Cifra de pe turn$demo$, public.check_chapter_text($demo$Pe turnul primăriei din Căluiești era un ecran mare, cât o ușă de garaj, și pe el scria în fiecare dimineață aceeași cifră: zero. Zero milimetri. Stația meteo automată, pe care comuna o primise printr-un program european cu trei ani înainte, avea o voce de femeie calmă, care anunța la ora șapte: „Probabilitate de precipitații pentru următoarele șapte zile: sub unu la sută. Consum recomandat de apă pe persoană: patruzeci de litri.”

Teo o ura. Nu stația, vocea. I se părea că vocea nu are nicio treabă cu ce înseamnă să te speli pe cap o dată pe săptămână, cu un lighean, în timp ce bunica stă în ușă și îți spune că pe vremea ei se spălau în gârlă și gârla era cât strada.

Teo avea cincisprezece ani și locuia cu bunica de când părinții plecaseră să muncească la Cluj, unde încă mai ploua. Bunica avea șaptezeci și opt și refuzase să plece. „Eu de aici nu mă mișc. Aici m-am născut, aici mi-a murit bărbatul, aici am rasadul.” Rasadul murise și el în al doilea an de secetă, dar bunica continua să ude un ghiveci de busuioc cu apă din rația ei, pe furiș, ca și cum Teo n-ar fi văzut.

În dimineața aceea de iunie, Teo a stat la coadă la cisternă cu cele două bidoane de douăzeci de litri, ca în fiecare marți și vineri. Coada era lungă și tăcută. Oamenii din Căluiești nu mai vorbeau despre ploaie, cum nu vorbești despre cineva care a plecat și nu mai scrie.

Băiatul de la cisternă era nou. Avea cam șaptesprezece ani, mâinile pline de ulei și o salopetă cu sigla stației de desalinizare de pe canal, cea care făcea apa sărată de la lac să fie aproape bună de băut. Când a ajuns rândul ei, i-a umplut bidoanele și i-a zis:

— Ai grijă la al doilea, are capacul crăpat.

— Știu, a zis Teo. E crăpat de un an.

— Îl pot lipi. Am la stație o rășină.

Teo a ridicat din umeri, așa cum ridici din umeri când nu vrei să arăți că ți-ar plăcea.

— Alin, a zis el.

— Teodora. Teo.

A plecat cu bidoanele atârnate de o cobiliță pe care bunica o adusese din pod în primul an de secetă, râzând că uite, s-au întors vremurile. Pe turn, vocea calmă anunța din nou zero. Teo s-a oprit, s-a uitat în sus la ecran și a zis, cu glas tare, pentru prima dată:

— Taci.

Un bătrân de la coadă a râs. A fost primul râs pe care l-a auzit în piața aia de luni de zile.$demo$), 1,
