where not exists (select 1 from public.chapters where chapters.id = '00000000-0000-4000-9100-001100030000'::uuid);

-- demo-12: "Robotul care aduna dimineți" by sofia_cerneala
insert into public.stories (id, user_id, slug, title, blurb, language_code, category_id,
  cover_kind, cover_design, cover_background, cover_accent, rating, ai_disclosure,
  first_published_at, last_chapter_published_at, created_at)
select '00000000-0000-4000-9100-001200000000'::uuid, '00000000-0000-4000-8000-000000000105'::uuid, 'robotul-care-aduna-dimineti-demo-12',
  $demo$Robotul care aduna dimineți$demo$, $demo$Pim e un robot de livrări bătrân, cu o roată care scârțâie și o memorie plină de răsărituri fotografiate de pe acoperișuri. Mai are nevoie de unul singur ca să-și termine colecția, dar luni îl duc la topit. Andrei, nouă ani, hotărăște că nu se poate așa ceva.$demo$, 'ro',
  (select id from public.categories where slug = 'fiction'),
  'drawn', 'dots', 'sky', 'plum', 'all_ages', 'no_ai',
  now() - interval '85 days', now() - interval '82 days', now() - interval '87 days'
where not exists (select 1 from public.stories where stories.id = '00000000-0000-4000-9100-001200000000'::uuid);
select public.set_story_tags('00000000-0000-4000-9100-001200000000'::uuid, '00000000-0000-4000-8000-000000000105'::uuid, array['robot', 'prietenie', 'răsărit', 'cartier', 'colecție']);
insert into public.chapters (id, story_id, user_id, code, position, draft_title, draft_body, draft_version,
  draft_saved_at, published_title, published_body, status, first_published_at, last_published_at, word_count,
  published_word_count, created_at)
select '00000000-0000-4000-9100-001200010000'::uuid, '00000000-0000-4000-9100-001200000000'::uuid, '00000000-0000-4000-8000-000000000105'::uuid,
  'd012c001', 1, $demo$Capitolul 1: Roata care scârțâie$demo$, public.check_chapter_text($demo$Andrei l-a auzit pe Pim înainte să-l vadă. Un scârțâit subțire, ca o ușă de dulap, venea dinspre scara blocului în fiecare dimineață pe la șase și jumătate, când el se trezea de la sine, fără ceas, așa cum fac copiii cărora le place ceva ce se întâmplă dimineața.

Pim era robotul de livrări al cartierului. Avea forma unei cutii de poștă pe roți, culoarea unui cer de toamnă, și pe față un ecran mic pe care apăreau două puncte și o linie, adică ochi și gură. Când scara era goală, se urca cu liftul până la ultimul etaj, ieșea pe acoperiș printr-o ușă pe care numai el știa s-o deschidă, și stătea acolo zece minute, nemișcat, cu fața spre răsărit.

Andrei a aflat asta pentru că l-a urmărit. A urcat pe scări, în vârful picioarelor, cu papucii în mână, și a deschis ușa de pe acoperiș tocmai când soarele ieșea de după blocurile din spate, roșu ca o caisă.

— Bună, a zis Pim, fără să se întoarcă. Nu face zgomot, te rog. Fac o fotografie.

Andrei a încremenit. Când soarele a fost tot deasupra blocurilor, Pim s-a întors spre el și pe ecran linia s-a curbat în sus.

— Gata. Numărul nouă sute nouăzeci și nouă.

— Nouă sute nouăzeci și nouă de ce?

— De dimineți. Le adun. Vrei să le vezi?

Pim a deschis o ușiță în lateral și a scos un ecran puțin mai mare. Pe el au început să curgă răsărituri: portocalii, roz, cenușii, unul aproape verde, unul cu zăpadă pe acoperișul vecin, unul cu un porumbel exact în mijloc. Fiecare avea o dată și un loc: acoperișul blocului C, acoperișul școlii, dealul de la marginea orașului, o dată chiar din curtea bisericii, de pe o bancă.

— De ce le aduni? a întrebat Andrei.

— Pentru că sunt diferite, a zis Pim. Oamenii cred că e același soare în fiecare zi. Nu e. Eu am dovezi.

Andrei s-a așezat pe marginea acoperișului, la distanță sigură, și a stat lângă Pim până a venit vremea de școală. Când a coborât, mama era în bucătărie și l-a întrebat unde a fost.

— Pe acoperiș. Cu robotul de livrări. Adună dimineți.

Mama a râs și i-a pus laptele în față. Andrei nu i-a explicat mai mult. Unele lucruri nu se explică, se arată, și pentru asta era nevoie de un răsărit.

A doua zi, când a urcat pe acoperiș, Pim nu era acolo. L-a găsit jos, în fața blocului, cu un afiș lipit pe ușiță: „Unitate retrasă din uz. Ridicare luni, ora 8.”

— Ce înseamnă retrasă din uz? a întrebat Andrei.

— Înseamnă că mă duc la topit, a zis Pim, cu vocea lui obișnuită. Și că mai am exact o dimineață, duminică, până la o mie. Dar duminică e înnorat.$demo$), 1,
